import{_ as n,C as a,o as i,c as h,E as o,a3 as l,w as g,j as t,a as r}from"./chunks/framework.B9M8MqoS.js";const p="/versions/v1.0.1/screens/devices/arpeggiator.png",c="/versions/v1.0.1/screens/devices/arpeggiator-free.png",T=JSON.parse('{"title":"Arpeggiator","description":"","frontmatter":{"title":"Arpeggiator","pageClass":"device-doc"},"headers":[],"relativePath":"devices/arpeggiator.md","filePath":"devices/arpeggiator.md"}'),u={name:"devices/arpeggiator.md"};function v(m,e,R,E,b,y){const d=a("DeviceHeading"),s=a("ManualRelated");return i(),h("div",null,[o(d,{slug:"arpeggiator",title:"Arpeggiator"}),e[1]||(e[1]=l('<p>Arpeggiate held notes</p><p><img src="'+p+'" alt="Arpeggiator: held C minor 7, SYNCED at RATE 1/16." class="screen"></p><p>On <strong>FREE</strong>, <strong>RATE</strong> is in milliseconds. Changing <strong>SYNC</strong> keeps the speed you hear: <strong>1/8</strong> at 120 BPM becomes <strong>250MS</strong>, and back. Switch back without touching <strong>RATE</strong> and you get exactly the rate you had, even after a tempo change. On <strong>SYNCED</strong>, a knob or an LFO on <strong>RATE</strong> steps through <a href="/versions/v1.0.1/concepts/mapping#knob-macros">note values</a>.</p><p><img src="'+c+'" alt="Arpeggiator: FREE at RATE 150MS." class="screen"></p><h2 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to &quot;When to use it&quot;">​</a></h2><p>Hold a chord and the Arpeggiator plays it note by note, in time. Let go and it stops. Try <strong>RATE 1/16</strong> with a short <strong>GATE</strong> for a classic synth arp.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Put a <a href="/versions/v1.0.1/devices/clock">Clock</a> before it in the rack. With <strong>SYNC</strong> on it doesn&#39;t play without one.</p></div><h2 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h2><div class="device-params-table"><table tabindex="0"><thead><tr><th>Parameter</th><th>Range</th><th>What it does</th></tr></thead><tbody><tr><td>BYPASS</td><td>OFF / ON</td><td>ON: MIDI passes through untouched. See <a href="/versions/v1.0.1/devices/#bypass">BYPASS</a>.</td></tr><tr><td>SYNC</td><td>FREE / SYNCED</td><td><strong>SYNCED</strong> steps with the Clock. <strong>FREE</strong> runs on its own.</td></tr><tr><td>RATE</td><td>1/64 – 1/1, or 50MS – 2000MS</td><td>Length of each step: a note value on <strong>SYNCED</strong>, milliseconds on <strong>FREE</strong>. Turn right for longer steps.</td></tr><tr><td>GATE</td><td>10% – 200%</td><td>Note length as a share of the step. Above 100% notes overlap.</td></tr><tr><td>CHORD</td><td>-2 – 2</td><td>Adds the same note one or two octaves up (+) or down (−) on every step.</td></tr><tr><td>OCTAVE</td><td>-5 – 5</td><td>Adds the held notes again, up to 5 octaves up (+) or down (−).</td></tr><tr><td>REPEAT</td><td>0 – 16</td><td>How many times the pattern plays before it stops. <strong>0</strong> plays until you let go.</td></tr><tr><td>RE-TRIG</td><td>OFF – 1/16</td><td>Starts the pattern again from its first note: on each new key, or every bar or note value.</td></tr><tr><td>STYLE</td><td>UP – RANDOM</td><td>Order the held notes play in.</td></tr></tbody></table></div><h2 id="parameter-values" tabindex="-1">Parameter values <a class="header-anchor" href="#parameter-values" aria-label="Permalink to &quot;Parameter values&quot;">​</a></h2><h3 id="re-trig" tabindex="-1">RE-TRIG <a class="header-anchor" href="#re-trig" aria-label="Permalink to &quot;RE-TRIG&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Value</th><th>What it does</th></tr></thead><tbody><tr><td>OFF</td><td>Never restarts.</td></tr><tr><td>NOTE</td><td>Restarts on each new key.</td></tr><tr><td>8BAR</td><td>Restarts every 8 bars.</td></tr><tr><td>4BAR</td><td>Restarts every 4 bars.</td></tr><tr><td>2BAR</td><td>Restarts every 2 bars.</td></tr><tr><td>1BAR</td><td>Restarts every bar.</td></tr><tr><td>1/2</td><td>Restarts every half note.</td></tr><tr><td>1/4</td><td>Restarts every quarter note.</td></tr><tr><td>1/8</td><td>Restarts every eighth note.</td></tr><tr><td>1/16</td><td>Restarts every sixteenth note.</td></tr></tbody></table><h3 id="style" tabindex="-1">STYLE <a class="header-anchor" href="#style" aria-label="Permalink to &quot;STYLE&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Value</th><th>What it does</th></tr></thead><tbody><tr><td>UP</td><td>Lowest to highest.</td></tr><tr><td>DOWN</td><td>Highest to lowest.</td></tr><tr><td>UP-DOWN</td><td>Up, then back down.</td></tr><tr><td>DOWN-UP</td><td>Down, then back up.</td></tr><tr><td>UP &amp; DOWN</td><td>Up, then down, playing the top and bottom notes twice.</td></tr><tr><td>DOWN &amp; UP</td><td>Down, then up, playing the top and bottom notes twice.</td></tr><tr><td>CONVERGE</td><td>Outside notes first, moving inward.</td></tr><tr><td>DIVERGE</td><td>Inside notes first, moving outward.</td></tr><tr><td>CON &amp; DIVERGE</td><td>Inward, then outward.</td></tr><tr><td>PINKY UP</td><td>The order you played them, starting from the lowest note.</td></tr><tr><td>PINKY UPDOWN</td><td>PINKY UP, then back.</td></tr><tr><td>THUMB UP</td><td>The order you played them, starting from the highest note.</td></tr><tr><td>THUMB UPDOWN</td><td>THUMB UP, then back.</td></tr><tr><td>PLAY ORDER</td><td>The order you played them.</td></tr><tr><td>VELOCITY UP</td><td>Softest to loudest.</td></tr><tr><td>VELOCITY DOWN</td><td>Loudest to softest.</td></tr><tr><td>CHORD TRIGGER</td><td>All held notes together on every step.</td></tr><tr><td>RANDOM</td><td>A random order, shuffled again when the chord changes.</td></tr></tbody></table><h3 id="repeat-and-re-trig" tabindex="-1">REPEAT and RE-TRIG <a class="header-anchor" href="#repeat-and-re-trig" aria-label="Permalink to &quot;REPEAT and RE-TRIG&quot;">​</a></h3><p>After the last cycle the arpeggio stops. Let go of all keys and play again to start a new set; MIDI Start also starts it again. A <strong>RE-TRIG</strong> restart doesn&#39;t count as a cycle.</p><p>With <strong>SYNC</strong> on, <strong>RE-TRIG</strong> bar and note values line up with the song position. A <strong>RE-TRIG</strong> as short as <strong>RATE</strong> or shorter restarts on every step, so only the first note plays.</p>',17)),o(s,null,{default:g(()=>[...e[0]||(e[0]=[t("ul",null,[t("li",null,[t("a",{href:"/versions/v1.0.1/racks/"},"Racks"),r(" — build a chain of devices")]),t("li",null,[t("a",{href:"/versions/v1.0.1/concepts/mapping"},"Mapping"),r(" — put a device setting on a knob or an LFO")]),t("li",null,[t("a",{href:"/versions/v1.0.1/concepts/modulation"},"Modulation"),r(" — move a setting while you play")])],-1)])]),_:1})])}const A=n(u,[["render",v]]);export{T as __pageData,A as default};
